## WebMCP tools
name="add_to_cart", description="Add a product to the cart. If the product has color options and none is given, the first option is used and reported back. Returns the full updated cart.", inputSchema={"type":"object","properties":{"slug":{"type":"string","description":"Slug of the product to add."},"quantity":{"type":"integer","minimum":1,"maximum":9,"description":"How many to add (default 1)."},"color":{"type":"string","description":"Color choice, for products with color options. If omitted, the first option is used and reported back."}},"required":["slug"],"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false}
name="apply_coupon", description="Apply one of the user's coupon codes to the cart. Returns the full updated cart including the discount.", inputSchema={"type":"object","properties":{"code":{"type":"string","description":"Coupon code, e.g. from get_my_coupons."}},"required":["code"],"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false}
name="check_compatibility", description="Check whether a product works with the user's existing gear (default) or with specific products. Returns per-item COMPATIBLE / INCOMPATIBLE / UNKNOWN / NOT_APPLICABLE with a reason and, for incompatibilities, the slug of a product that fixes it. Always call this for each machine before recommending one.", inputSchema={"type":"object","properties":{"candidate_slug":{"type":"string","description":"Slug of the product you're considering buying."},"against_slugs":{"type":"array","items":{"type":"string"},"description":"Optional: check against these specific product slugs instead of everything the user owns."}},"required":["candidate_slug"],"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false}
name="checkout", description="Place the order for everything in the cart. Irreversible. Only call when the user explicitly asks to buy / check out / place the order.", inputSchema={"type":"object","properties":{},"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false}
name="clear_highlights", description="Remove highlighting from the Compare view.", inputSchema={"type":"object","properties":{},"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false}
name="compare_products", description="Side-by-side spec matrix for 2–3 products. Each row has a `differs` flag; focus on rows where `differs` is true.", inputSchema={"type":"object","properties":{"slugs":{"type":"array","items":{"type":"string"},"minItems":2,"maxItems":3,"description":"2–3 product slugs to compare side by side."}},"required":["slugs"],"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false}
name="get_cart", description="The user's current cart: lines with color and quantity, subtotal, applied coupon and total.", inputSchema={"type":"object","properties":{},"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false}
name="get_compare_list", description="The products the user currently has open in the Compare view. Call this first when the user says 'these two' or 'which one'.", inputSchema={"type":"object","properties":{},"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false}
name="get_my_coupons", description="Discount codes available to this user. Call before apply_coupon.", inputSchema={"type":"object","properties":{},"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false}
name="get_my_gear", description="Everything the user has previously bought from this store, with purchase dates. Use it to check what they already own before recommending anything.", inputSchema={"type":"object","properties":{},"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false}
name="get_product_details", description="Full specification sheet for one product, including fields not shown on the product page, and the source the specs came from.", inputSchema={"type":"object","properties":{"slug":{"type":"string","description":"The product's slug, as returned by search_products."}},"required":["slug"],"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false}
name="highlight_differences", description="Visually highlight specific rows in the user's Compare view and dim the rest, so they can see why you recommend what you recommend. Use the `key` values from compare_products. Optional `note` is shown above the table. Call this when you've decided which specs matter for the user's needs.", inputSchema={"type":"object","properties":{"spec_keys":{"type":"array","items":{"type":"string","enum":["boilerConfig","brewBoilerL","groupType","portafilterFit","basketMm","pid","preInfusion","flowControl","pumpType","brewPressureGauge","shotTimer","steamBoilerL","simultaneousBrewSteam","steamWand","hotWaterSpout","heatUpMinutes","widthCm","depthCm","heightCm","weightKg","waterTankL","waterTankPosition","plumbable","noiseDb","wattage","voltage","cupClearanceCm","dripTray","ecoMode","autoOff","appControl","caseMaterial","boilerMaterial","powerCableM","display","warrantyYears","colorOptions","madeIn","certification","priceEur"]},"minItems":1,"description":"The spec row keys to highlight — use the `key` values returned by compare_products."},"note":{"type":"string","description":"Optional one-sentence explanation shown to the user above the table."}},"required":["spec_keys"],"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false}
name="remove_from_cart", description="Remove a product from the cart. Returns the full updated cart.", inputSchema={"type":"object","properties":{"slug":{"type":"string","description":"Slug of the product in the cart."},"color":{"type":"string","description":"Color of the cart line, when the product is in the cart in more than one color."}},"required":["slug"],"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false}
name="search_products", description="Search the store catalog by free text and/or category. Returns product slugs, names, prices and key compatibility fields. Use the returned slugs with other tools.", inputSchema={"type":"object","properties":{"query":{"type":"string","description":"Free-text search over product names, brands and descriptions."},"category":{"type":"string","enum":["MACHINE","GRINDER","PORTAFILTER","BASKET","TAMPER","PUCK_SCREEN","DOSING_FUNNEL","WDT_TOOL","WATER_FILTER","ACCESSORY"],"description":"Filter to one product category."}},"additionalProperties":false}, annotations={"readOnly":true,"untrustedContent":false}
name="set_compare_list", description="Replace the products shown in the Compare view.", inputSchema={"type":"object","properties":{"slugs":{"type":"array","items":{"type":"string"},"maxItems":3,"description":"0–3 product slugs to show in the Compare view."}},"required":["slugs"],"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false}
name="update_cart_quantity", description="Change the quantity of a cart line (0 removes it). Returns the full updated cart.", inputSchema={"type":"object","properties":{"slug":{"type":"string","description":"Slug of the product in the cart."},"color":{"type":"string","description":"Color of the cart line, when the product is in the cart in more than one color."},"quantity":{"type":"integer","minimum":0,"maximum":9,"description":"New quantity; 0 removes the line."}},"required":["slug","quantity"],"additionalProperties":false}, annotations={"readOnly":false,"untrustedContent":false}

